/**
 * Error surface for the entire FFI. UniFFI maps this to a Kotlin sealed
 * class hierarchy and a Swift enum with associated values.
 */
sealed class SmritidbException : kotlin.Exception() {
  /**
   * Cue/vector dimension does not match the store's configured dimension.
   */
  class DimensionMismatch : SmritidbException() {
    override val message
      get() = ""
  }

  /**
   * Invalid store/persistence configuration (e.g. dim < 1024).
   */
  class InvalidConfig : SmritidbException() {
    override val message
      get() = ""
  }

  /**
   * Item value exceeds the configured `value_cap_bytes`.
   */
  class ValueTooLarge : SmritidbException() {
    override val message
      get() = ""
  }

  /**
   * Item with the given id was not found.
   */
  class NotFound : SmritidbException() {
    override val message
      get() = ""
  }

  /**
   * Caller passed an empty input where one is not allowed.
   */
  class EmptyInput : SmritidbException() {
    override val message
      get() = ""
  }

  /**
   * Underlying I/O failure (filesystem, etc.). Message is host-facing.
   *
   * Patched: constructor parameter renamed from `message` -> `msg` so it
   * doesn't shadow `kotlin.Throwable.message`. The inherited `message`
   * still surfaces the inner string via `override`.
   */
  class Io(
    val `msg`: kotlin.String,
  ) : SmritidbException() {
    override val message
      get() = "message=${ `msg` }"
  }

  /**
   * Underlying database failure (SQLite, etc.). Message is host-facing.
   */
  class Database(
    val `msg`: kotlin.String,
  ) : SmritidbException() {
    override val message
      get() = "message=${ `msg` }"
  }

  /**
   * Snapshot or WAL on disk was unreadable / violated invariants.
   */
  class Corruption(
    val `msg`: kotlin.String,
  ) : SmritidbException() {
    override val message
      get() = "message=${ `msg` }"
  }

  /**
   * JSON / KMF encoding or decoding failure.
   */
  class Encoding(
    val `msg`: kotlin.String,
  ) : SmritidbException() {
    override val message
      get() = "message=${ `msg` }"
  }

  /**
   * Catch-all adapter or store failure.
   */
  class Other(
    val `msg`: kotlin.String,
  ) : SmritidbException() {
    override val message
      get() = "message=${ `msg` }"
  }

  companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SmritidbException> {
    override fun lift(error_buf: RustBuffer.ByValue): SmritidbException = FfiConverterTypeSmritidbError.lift(error_buf)
  }
}

/**
 * @suppress
 */
public object FfiConverterTypeSmritidbError : FfiConverterRustBuffer<SmritidbException> {
  override fun read(buf: ByteBuffer): SmritidbException =
    when (buf.getInt()) {
      1 -> SmritidbException.DimensionMismatch()
      2 -> SmritidbException.InvalidConfig()
      3 -> SmritidbException.ValueTooLarge()
      4 -> SmritidbException.NotFound()
      5 -> SmritidbException.EmptyInput()
      6 ->
        SmritidbException.Io(
          FfiConverterString.read(buf),
        )
      7 ->
        SmritidbException.Database(
          FfiConverterString.read(buf),
        )
      8 ->
        SmritidbException.Corruption(
          FfiConverterString.read(buf),
        )
      9 ->
        SmritidbException.Encoding(
          FfiConverterString.read(buf),
        )
      10 ->
        SmritidbException.Other(
          FfiConverterString.read(buf),
        )
      else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
    }

  override fun allocationSize(value: SmritidbException): ULong =
    when (value) {
      is SmritidbException.DimensionMismatch -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL
      )
      is SmritidbException.InvalidConfig -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL
      )
      is SmritidbException.ValueTooLarge -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL
      )
      is SmritidbException.NotFound -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL
      )
      is SmritidbException.EmptyInput -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL
      )
      is SmritidbException.Io -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL +
          FfiConverterString.allocationSize(value.`msg`)
      )
      is SmritidbException.Database -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL +
          FfiConverterString.allocationSize(value.`msg`)
      )
      is SmritidbException.Corruption -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL +
          FfiConverterString.allocationSize(value.`msg`)
      )
      is SmritidbException.Encoding -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL +
          FfiConverterString.allocationSize(value.`msg`)
      )
      is SmritidbException.Other -> (
        // Add the size for the Int that specifies the variant plus the size needed for all fields
        4UL +
          FfiConverterString.allocationSize(value.`msg`)
      )
    }

  override fun write(
    value: SmritidbException,
    buf: ByteBuffer,
  ) {
    when (value) {
      is SmritidbException.DimensionMismatch -> {
        buf.putInt(1)
        Unit
      }
      is SmritidbException.InvalidConfig -> {
        buf.putInt(2)
        Unit
      }
      is SmritidbException.ValueTooLarge -> {
        buf.putInt(3)
        Unit
      }
      is SmritidbException.NotFound -> {
        buf.putInt(4)
        Unit
      }
      is SmritidbException.EmptyInput -> {
        buf.putInt(5)
        Unit
      }
      is SmritidbException.Io -> {
        buf.putInt(6)
        FfiConverterString.write(value.`msg`, buf)
        Unit
      }
      is SmritidbException.Database -> {
        buf.putInt(7)
        FfiConverterString.write(value.`msg`, buf)
        Unit
      }
      is SmritidbException.Corruption -> {
        buf.putInt(8)
        FfiConverterString.write(value.`msg`, buf)
        Unit
      }
      is SmritidbException.Encoding -> {
        buf.putInt(9)
        FfiConverterString.write(value.`msg`, buf)
        Unit
      }
      is SmritidbException.Other -> {
        buf.putInt(10)
        FfiConverterString.write(value.`msg`, buf)
        Unit
      }
    }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
  }
}

/**
 * @suppress
 */
public object FfiConverterOptionalString : FfiConverterRustBuffer<kotlin.String?> {
  override fun read(buf: ByteBuffer): kotlin.String? {
    if (buf.get().toInt() == 0) {
      return null
    }
    return FfiConverterString.read(buf)
  }

  override fun allocationSize(value: kotlin.String?): ULong {
    if (value == null) {
      return 1UL
    } else {
      return 1UL + FfiConverterString.allocationSize(value)
    }
  }

  override fun write(
    value: kotlin.String?,
    buf: ByteBuffer,
  ) {
    if (value == null) {
      buf.put(0)
    } else {
      buf.put(1)
      FfiConverterString.write(value, buf)
    }
  }
}

/**
 * @suppress
 */
public object FfiConverterSequenceFloat : FfiConverterRustBuffer<List<kotlin.Float>> {
  override fun read(buf: ByteBuffer): List<kotlin.Float> {
    val len = buf.getInt()
    return List<kotlin.Float>(len) {
      FfiConverterFloat.read(buf)
    }
  }

  override fun allocationSize(value: List<kotlin.Float>): ULong {
    val sizeForLength = 4UL
    val sizeForItems = value.map { FfiConverterFloat.allocationSize(it) }.sum()
    return sizeForLength + sizeForItems
  }

  override fun write(
    value: List<kotlin.Float>,
    buf: ByteBuffer,
  ) {
    buf.putInt(value.size)
    value.iterator().forEach {
      FfiConverterFloat.write(it, buf)
    }
  }
}

