/**
 * Element-wise XOR. Self-inverse — `bind(bind(a, b), b) == a`.
 */
@Throws(SmritidbException::class)
fun `bind`(
  `a`: kotlin.ByteArray,
  `b`: kotlin.ByteArray,
): kotlin.ByteArray =
  FfiConverterByteArray.lift(
    uniffiRustCallWithError(SmritidbException) { _status ->
      UniffiLib.INSTANCE.uniffi_smritidb_ffi_fn_func_bind(FfiConverterByteArray.lower(`a`), FfiConverterByteArray.lower(`b`), _status)
    },
  )

/**
 * Element-wise majority over a list of hypervectors. Ties resolved
 * deterministically per SPEC §1.3.
 */
@Throws(SmritidbException::class)
fun `bundle`(`hvs`: List<kotlin.ByteArray>): kotlin.ByteArray =
  FfiConverterByteArray.lift(
    uniffiRustCallWithError(SmritidbException) { _status ->
      UniffiLib.INSTANCE.uniffi_smritidb_ffi_fn_func_bundle(FfiConverterSequenceByteArray.lower(`hvs`), _status)
    },
  )

/**
 * Map an embedding (a `[-1, 1]`-bounded float vector) to a hypervector
 * that approximately preserves cosine similarity.
 */
fun `encodeEmbedding`(
  `embedding`: List<kotlin.Float>,
  `dim`: kotlin.UInt,
): kotlin.ByteArray =
  FfiConverterByteArray.lift(
    uniffiRustCall { _status ->
      UniffiLib.INSTANCE.uniffi_smritidb_ffi_fn_func_encode_embedding(
        FfiConverterSequenceFloat.lower(`embedding`),
        FfiConverterUInt.lower(`dim`),
        _status,
      )
    },
  )

/**
 * Map a UTF-8 string to a hypervector via BLAKE3-derived randomness.
 */
fun `encodeString`(
  `s`: kotlin.String,
  `dim`: kotlin.UInt,
