  FfiConverterByteArray.lift(
    uniffiRustCall { _status ->
      UniffiLib.INSTANCE.uniffi_smritidb_ffi_fn_func_encode_string(FfiConverterString.lower(`s`), FfiConverterUInt.lower(`dim`), _status)
    },
  )

