 * Cyclic bit rotation by `k`. Positive `k` rotates forward.
 */
fun `permute`(
  `hv`: kotlin.ByteArray,
  `k`: kotlin.Int,
): kotlin.ByteArray =
  FfiConverterByteArray.lift(
    uniffiRustCall { _status ->
      UniffiLib.INSTANCE.uniffi_smritidb_ffi_fn_func_permute(FfiConverterByteArray.lower(`hv`), FfiConverterInt.lower(`k`), _status)
    },
  )

/**
 * Deterministic random binary hypervector from a seed.
 * `dim` MUST be >= 1024. Hypervectors are returned as packed bytes
 * (one byte per bit; 0 or 1) per SPEC §1.1.
 */
